Huffman.algorithm:
// Узел дерева Хаффмана
class HuffmanNode:
    def __init__(self, char, freq):
        self.char = char
        self.freq = freq
        self.left = None
        self.right = None

function build_huffman_tree(chars, freqs):
    // Создаем узлы для каждого символа
    nodes = []
    for i in range(len(chars)):
        nodes.append(HuffmanNode(chars[i], freqs[i]))

    // Используем мин-кучу для частот
    heap = MinHeap(nodes)

    // Строим дерево
    while len(heap) > 1:
        // Берем два узла с наименьшей частотой
        left = heap.extract_min()
        right = heap.extract_min()

        // Создаем новый узел
        merged = HuffmanNode(None, left.freq + right.freq)
        merged.left = left
        merged.right = right

        heap.insert(merged)

    return heap.extract_min()

function generate_codes(node, code='', codes={}):
    if node is None:
        return

    if node.char is not None:
        codes[node.char] = code
        return

    generate_codes(node.left, code + '0', codes)
    generate_codes(node.right, code + '1', codes)
